sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var ym = api.state.yearMonth;
    var day = api.state.day;
    let editSysId = api.state.row;

    let hatureibi = '';

    if(ym == null && day == null){
        hatureibi = hatureibi;
    }else {
        hatureibi = ym + '-' + day;
    }

    let info = {
        hatureibi : hatureibi,
        editSysId : editSysId
    };

    api.data.update_hatureibi_1.execute(info);
}
